import{reflexPoints,synapseState}from './neural-models.js?v=20261023-physicscomplete01';
const material=(T,c,opts={})=>new T.MeshStandardMaterial({color:c,roughness:.3,metalness:.03,...opts});
function ball(g,T,p,r,c,name,scale=[1,1,1]){let m=new T.Mesh(new T.SphereGeometry(r,28,20),material(T,c));m.position.set(...p);m.scale.set(...scale);m.name=name||'';g.add(m);return m;}
function rod(g,T,a,b,r,c,name){let p=new T.Vector3(...a),q=new T.Vector3(...b),d=q.clone().sub(p),m=new T.Mesh(new T.CylinderGeometry(r,r,d.length(),20),material(T,c));m.position.copy(p.add(q).multiplyScalar(.5));m.quaternion.setFromUnitVectors(new T.Vector3(0,1,0),d.normalize());m.name=name||'';g.add(m);}
export function buildNeural(g,T,w={}){let k=w.kind||'neuron',s=w.state||'normal';
if(k==='synapse'){let step=w.step??5,f=synapseState({step,release:s!=='release-off',receptor:s!=='receptor-off'});for(let side of[-1,1]){ball(g,T,[side*1.05,0,0],.7,side<0?0x9fbfba:0xc5a78f,side<0?'sending-terminal':'receiving-membrane',[1,.9,.75]);rod(g,T,[side*1.5,0,0],[side*2,0,0],.14,0xb8ccca);}if(s!=='receptor-off')for(let i=0;i<5;i++){let y=-.5+i*.25;rod(g,T,[.42,y,0],[.3,y,.12],.035,0xb4d1d3,'receptor');}if(f.transmitter)for(let i=0;i<5;i++)ball(g,T,[f.bound?.26:-.2+i*.08,-.45+i*.22,.25],.055,0xead0a6,'transmitter');else for(let i=0;i<5;i++)ball(g,T,[-1.2+i*.1,.15+(i%2)*.2,.3],.06,0xead0a6,'stored-transmitter');if(f.nextImpulse)ball(g,T,[1.7,0,.2],.1,0xf2c49e,'next-impulse');if(step<2)ball(g,T,[-1.8+step*.7,0,.2],.1,0xf2c49e,'arriving-impulse');return;}
if(k==='reflex'){rod(g,T,[.65,-1.2,-.3],[.65,1.2,-.3],.22,0xc1a28e,'spinal-cord');reflexPoints.forEach((p,i)=>{ball(g,T,p,i===0||i===6?.2:.1,i<=2?0xb0c9ce:0xd4af92,'reflex-'+i);if(i)rod(g,T,reflexPoints[i-1],p,.045,i<=3?0xabc5cc:0xd7b397,'reflex-link');});let p=reflexPoints[Math.min(6,w.step??(s==='motor'?5:s==='sensory'?1:0))];ball(g,T,[p[0],p[1],.25],.13,0xf2d09f,'signal-marker');return;}
if(k==='control'){rod(g,T,[-1.5,-1,0],[1.5,-1,0],.04,0xb1c9cb,'axis');rod(g,T,[0,-1,0],[0,1.2,0],.04,0xb1c9cb,'axis');rod(g,T,[-1.3,0,0],[1.3,0,0],.025,0xe1c29b,'target');let val=w.value??(s==='above'?8:s==='below'?2:5);ball(g,T,[0,(val-5)*.22,.2],.2,0xe1af95,'controlled-value');return;}
if(k==='ruler'){let m=new T.Mesh(new T.BoxGeometry(.45,2.8,.08),material(T,0xd5be98));m.name='ruler';g.add(m);for(let i=0;i<11;i++)rod(g,T,[-.22,-1.2+i*.24,.08],[-.03,-1.2+i*.24,.08],.012,0x38566a,'scale-mark');rod(g,T,[-1,-.7,.1],[-.3,-.7,.1],.11,0xd1a68e,'finger');rod(g,T,[.3,-.7,.1],[1,-.7,.1],.11,0xd1a68e,'finger');return;}
ball(g,T,[-1.3,0,0],.38,0x9ebeba,'cell-body');ball(g,T,[-1.3,0,.28],.15,0x8d7893,'nucleus');rod(g,T,[-.95,0,0],[1.55,0,0],.055,0xacc8c5,'axon');for(let i=0;i<5;i++)rod(g,T,[-.7+i*.42,0,0],[-.43+i*.42,0,0],.13,0xd6b996,'myelin');for(let a of[-1,-.5,.5,1]){let p=[-1.7,Math.sin(a)*.8,Math.cos(a)*.3];rod(g,T,[-1.5,0,0],p,.045,0xa9c7c3,'dendrite');rod(g,T,p,[-2,Math.sin(a)*1.1,Math.cos(a)*.4],.025,0xa9c7c3,'dendrite');}for(let a of[-.7,0,.7])rod(g,T,[1.5,0,0],[2,Math.sin(a)*.7,.1],.04,0xb6d0ca,'terminal-branch');ball(g,T,[w.step===undefined?.15:-.8+Math.min(5,w.step)*.4,0,.18],.09,0xf0c49e,'impulse-tracer');}
